// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;

    receive() external payable {}

    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 balance, uint256 value) public {
        balance = bound(balance, 1, 100 ether);
        value = bound(value, 0, 200 ether);
        vm.deal(address(c), balance);

        bool ok;
        try c.withdraw(value) { ok = true; } catch { ok = false; }

        // Rule: withdraw(v) succeeds iff v <= the contract's balance.
        assertTrue(ok == (value <= balance));
    }
}
